# ------------------------------------------------------------------ symbols
def original_symbols():
    out = {}
    for f in SYMBOL_FILES:
        for line in open(os.path.join(ROOT, 'decomp/config/us', f)):
            m = re.match(r'(\w+)\s*=\s*(0x[0-9A-Fa-f]+);', line)
            if m: out.setdefault(m.group(1), int(m.group(2), 16))
    return {t: (out[ORIGINAL_NAMES.get(sym, sym)], size) for t, _, sym, size in TABLES
            if size is not None and ORIGINAL_NAMES.get(sym, sym) in out}


def elf_symbols(path):
    """{table: (address, size)} from the symbol table of a linked ELF (32-bit little endian)."""
    d = open(path, 'rb').read()
    assert d[:4] == b'\x7fELF' and d[4] == 1 and d[5] == 1, f'{path}: not an ELF32 LE'
    shoff, = struct.unpack_from('<I', d, 0x20)
    shentsize, shnum = struct.unpack_from('<HH', d, 0x2E)
    secs = [struct.unpack_from('<10I', d, shoff + i * shentsize) for i in range(shnum)]
    want = {sym: t for t, _, sym, _ in TABLES}; out = {}
    for s in secs:
        if s[1] != 2: continue                                     # SHT_SYMTAB
        strtab = secs[s[6]]
        for k in range(s[5] // 16):
            name, value, size, _, _, _ = struct.unpack_from('<IIIBBH', d, s[4] + 16 * k)
            p = strtab[4] + name; n = d[p:d.index(b'\0', p)].decode()
            if n in want and size: out[want[n]] = (value, size)
    missing = [sym for sym, t in want.items() if t not in out and t not in OPTIONAL]
    if missing: raise SystemExit(f'{path}: no symbol {", ".join(missing)}')
    return out


class Exe:
    """The balance tables of one executable + overlays folder (original: extracted/, or a compiled build)."""

    def __init__(self, folder=None):
        self.folder = folder or EXTRACTED
        elf = os.path.join(self.folder, 'SLUS_010.32.elf')
        self.compiled = os.path.exists(elf)
        self.syms = elf_symbols(elf) if self.compiled else original_symbols()
        self.files = {}

    def path(self, f):
        if os.path.exists(os.path.join(self.folder, f)): return os.path.join(self.folder, f)
        hits = glob.glob(os.path.join(self.folder, '**', f), recursive=True)
        if not hits: raise SystemExit(f'{self.folder}: no {f}')
        return hits[0]

    def data(self, f):
        if f not in self.files: self.files[f] = bytearray(open(self.path(f), 'rb').read())
        return self.files[f]

    def where(self, table):
        f = next(x[1] for x in TABLES if x[0] == table)
        addr, size = self.syms[table]
        return f, addr - FILE_BASE[f], size

    def has(self, table):
        return table in self.syms

    def raw(self, table):
        f, off, size = self.where(table)
        return bytes(self.data(f)[off:off + size])

    def write(self, table, blob):
        f, off, size = self.where(table)
        assert len(blob) == size, (table, len(blob), size)
        self.data(f)[off:off + size] = blob


# ------------------------------------------------------------------ codecs: table bytes <-> JSON document
def _rows(fields, raw):
    n = struct.calcsize(SP._fmt(fields))
    if len(raw) % n: raise SystemExit(f'table of {len(raw)} bytes is not a whole number of {n}-byte rows')
    return [SP.unpack(fields, raw, i * n) for i in range(len(raw) // n)]


def _strip(d):
    """A copy without comment keys ("_...")."""
    if isinstance(d, dict): return {k: _strip(v) for k, v in d.items() if not str(k).startswith('_')}
    if isinstance(d, list): return [_strip(v) for v in d]
    return d


def decode(exe):
    """Every table of an executable as one JSON document (comments added by annotate())."""
    doc = {'species': {}, 'techniques': {}}
    sp = lambda t: doc['species'].setdefault(str(t), {})
    for t, r in enumerate(_rows(SP.PARA_FIELDS, exe.raw('para'))): sp(t)['para'] = r
    for key, fields in (('raise', SP.RAISE_FIELDS), ('evoReqs', SP.REQ_FIELDS), ('evoGains', SP.GAIN_FIELDS)):
        for t, r in enumerate(_rows(fields, exe.raw(key))): sp(t)[key] = r
    raw = exe.raw('evoPaths'); w = 1 if len(raw) == 62 * 11 else 2     # s8 (original) or DigimonId s16 (mod)
    for i in range(len(raw) // (11 * w)):
        v = struct.unpack_from('<11' + 'bh'[w - 1], raw, i * 11 * w)
        sp(i + 1)['evoPaths'] = {'from': list(v[:5]), 'to': list(v[5:])}
    for i, v in enumerate(struct.unpack(f'<{len(exe.raw("itemTakeDistance"))}b', exe.raw('itemTakeDistance'))):
        if i + 1 < NUM_ORIGINAL: sp(i + 1)['itemTakeDistance'] = v
        elif v: raise SystemExit(f'ITEM_TAKE_DISTANCE: the row of type {i + 1} (no species) is {v}, not 0')
    decode_species_tables(exe, sp)
    for i, r in enumerate(_rows(MOVE_FIELDS, exe.raw('techniques'))): doc['techniques'][str(i)] = r
    lc = exe.raw('learnChances')
    for i in range(len(lc) // 3): doc['techniques'][str(i)]['learnChances'] = list(lc[3 * i:3 * i + 3])
    tf = exe.raw('typeFactors'); doc['typeFactors'] = [list(tf[7 * i:7 * i + 7]) for i in range(7)]
    doc['evolutionItems'] = {str(0x47 + i): v for i, v in enumerate(exe.raw('evolutionItems'))}
    jc = exe.raw('joinChances'); doc['joinChances'] = [list(jc[3 * i:3 * i + 3]) for i in range(4)]
    doc['items'] = {str(i): r for i, r in enumerate(_rows(ITEM_FIELDS, exe.raw('items')))}
    sc = exe.raw('schedule'); doc['tournaments'] = {'schedule': [list(sc[6 * i:6 * i + 6]) for i in range(30)]}
    doc['tournaments']['opponentBaseStats'] = list(struct.unpack('<24h', exe.raw('opponentBaseStats')))
    wc = exe.raw('winChances'); doc['tournaments']['winChances'] = [list(wc[3 * i:3 * i + 3]) for i in range(4)]
    for suffix, key in (('', 'brainTraining'),):        # (TRN2 has no brains gym: TRN2_D_8008DAD0/DB08 are TrainingSpot arrays)
        bt = exe.raw('brainTechs' + suffix); bw = struct.unpack('<24b', exe.raw('brainWeights' + suffix))
        doc[key] = {'techniques': {e: list(bt[8 * i:8 * i + 8]) for i, e in enumerate(ELEMENTS)},
                    'weights': [list(bw[3 * i:3 * i + 3]) for i in range(8)]}
    raw = exe.raw('screens'); doc['screens'] = {}
    for i in range(len(raw) // 16):                     # MAP_ENTRIES: the screens (map.h MapEntry)
        name = raw[16 * i:16 * i + 10]
        n8, n4, fl, dr, to, lb = struct.unpack_from('<bbBbbB', raw, 16 * i + 10)
        doc['screens'][str(i)] = {'file': name.rstrip(b'\0').decode('latin-1'), 'fileBytes': list(name),
                                  'tims8': n8, 'tims4': n4, 'flags': fl, 'doors': dr, 'toilet': to, 'caption': lb}
    raw = exe.raw('doors'); doc['doors'] = []
    for i in range(len(raw) // 54):                     # DOOR_MAPDATA: 6 doors per group (model, x, y, z, rotation)
        mid = struct.unpack_from('<6B', raw, 54 * i); v = struct.unpack_from('<24h', raw, 54 * i + 6)
        doc['doors'].append([[mid[k], v[k], v[6 + k], v[12 + k], v[18 + k]] for k in range(6)])
    raw = exe.raw('toilets')
    doc['toilets'] = [list(struct.unpack_from('<4h', raw, 8 * i)) for i in range(len(raw) // 8)]
    if exe.has('donorEntries'): doc['effectDonors'] = decode_donors(exe)
    for k in NAMED_RULES:
        if exe.has(k): doc[k] = decode_named(k, exe)
    for k, _, _, fmt, fields in SMALL_TABLES:
        if k in OPTIONAL and not exe.has(k): continue
        raw = exe.raw(k); n = struct.calcsize(fmt)
        rows = [struct.unpack_from(fmt, raw, n * i) for i in range(len(raw) // n)]
        doc[k] = [{f: v for f, v in zip(fields, r) if f not in KEEP.get(k, ())} for r in rows] if fields else [r[0] if len(r) == 1 else list(r) for r in rows]
    return doc


