# the fight runs in real time, one logic tick every 50 ms (20 Hz at any presented frame rate): its durations are written in milliseconds
# and become ticks in the table; a key in EXTRA_MS is the longest extra wait of a die (the slot holds its number of faces: ms / tick + 1)
TICK_MS = 50
REAL_MS = {'battleFormulas': {'block.invulnerableMs', 'status.poisonIntervalMs', 'status.confusionMs', 'status.stunMs', 'status.flatMs',
                              'cooldown.afterAttackMs', 'cooldown.noTargetMs', 'senile.durationMs', 'senile.intervalMsPerStep',
                              'flee.ignoreHitsFromMs', 'flee.lockMs', 'finisher.chargeWindowMs', 'finisher.holdMs', 'flatten.retargetMs',
                              'flatten.attackRepeatMs', 'flatten.attackDelayMs', 'buffs.priorityStepMs', 'speed.stepMs', 'approach.timeoutMs',
                              'approach.tournamentTimeoutMs', 'approach.tournamentRestMs', 'defeat.countdownShowMs', 'defeat.endMs',
                              'afterFight.settleMs', 'defeat.digitMs'}}
REAL_MS['trainRules'] = REAL_MS['train2Rules'] = {'session.durationMs', 'session.stepMs'}   # a gym session runs on logic ticks too
REAL_MS['fishingRules'] = {'tension.snapStepMs', 'hook.pressedMsForPull', 'theft.everyMs'}   # fishing runs one logic tick per 50 ms too
EXTRA_MS = {'battleFormulas': {'status.confusionExtraMs', 'status.stunExtraMs', 'status.flatExtraMs'}}
_REAL = re.compile(r'(?:(\d+)s)?(?:(\d+)ms)?')


def real_ticks(v, where, extra=False):
    """Ticks of a real-time wait written as whole milliseconds or text like "250ms", "2s", "1s500ms"; only multiples of one tick (50 ms)."""
    if isinstance(v, bool): raise SystemExit(f'{where}: a time in milliseconds')
    if isinstance(v, str):
        m = _REAL.fullmatch(v)
        if not m or not any(m.groups()): raise SystemExit(f'{where}: "{v}" is not a time (milliseconds, or like "250ms", "2s", "1s500ms")')
        v = int(m.group(1) or 0) * 1000 + int(m.group(2) or 0)
    if not isinstance(v, int) or v < 0: raise SystemExit(f'{where}: a time in milliseconds (0 or more)')
    if v % TICK_MS: raise SystemExit(f'{where}: {v} ms; real-time waits (the fight, fishing) move in steps of {TICK_MS} ms')
    return v // TICK_MS + (1 if extra else 0)
NAMED_FMT = {'newGame': 'i', 'economy': 'i'}                      # the slots of a table are 16-bit unless it is here
NAMED_LIMITS = {('clock', 'dayRealSeconds'): (144, 32767)}      # below 144 s a day, one tick would skip over the shortest care periods
_DURATION = re.compile(r'(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?')


def parse_duration(v, where):
    """Game seconds of a whole number (seconds) or of text like "45s", "10m", "1h", "1h30m"."""
    if isinstance(v, bool): raise SystemExit(f'{where}: a duration')
    if isinstance(v, int): return v
    m = _DURATION.fullmatch(v) if isinstance(v, str) else None
    if not m or not any(m.groups()): raise SystemExit(f'{where}: "{v}" is not a duration (game seconds, or like "45s", "10m", "1h30m")')
    h, mi, s = (int(x or 0) for x in m.groups())
    return h * 3600 + mi * 60 + s


def duration_frames(v, where):
    sec = parse_duration(v, where)
    if sec % FRAME_SECONDS: raise SystemExit(f'{where}: {sec} s; game time moves in steps of {FRAME_SECONDS} s')
    return sec // FRAME_SECONDS


_SEG = re.compile(r'(\w+)(?:\[(\d+)\])?$')


def _get(obj, path):
    for h in path.split('.'):
        m = _SEG.match(h); d = obj.get(m.group(1)) if isinstance(obj, dict) else None
        if m.group(2) is not None: d = d[int(m.group(2))] if isinstance(d, list) and int(m.group(2)) < len(d) else None
        obj = d
        if obj is None: return None
    return obj


def _set(out, path, v):
    *head, last = path.split('.')
    for h in head: out = out.setdefault(h, {})
    m = _SEG.match(last)
    if m.group(2) is None: out[last] = v
    else:
        lst = out.setdefault(m.group(1), []); i = int(m.group(2))
        lst += [-1] * (i + 1 - len(lst)); lst[i] = v


def decode_named(key, exe):
    """The JSON object of a NAMED_RULES table from the compiled executable (slots at -1 are left out)."""
    raw = exe.raw(key); fmt = NAMED_FMT.get(key, "h"); out = {}
    vals = struct.unpack(f'<{len(raw) // struct.calcsize(fmt)}{fmt}', raw)   # fewer slots: an executable from before the table grew
    for path, v in zip(NAMED_RULES[key], vals):
        if path is not None and v != -1:
            if path in REAL_MS.get(key, ()): v *= TICK_MS
            elif path in EXTRA_MS.get(key, ()): v = (v - 1) * TICK_MS
            elif path in TIME_SLOTS.get(key, ()): v *= FRAME_SECONDS
            _set(out, path, v)
    if key == 'newGame' and len(raw) == 80 + 224 and raw[80:] != b'\xff' * 224:
        import starter_quiz
        out.update(starter_quiz.unpack(raw[80:]))
    return out


ITEM_EFFECT_FIELDS = ['energy', 'happiness', 'weight', 'tiredness', 'discipline', 'lifetime', 'addHP', 'addMP', 'healHP', 'healMP', 'addOffense', 'addDefense', 'addSpeed', 'addBrain', 'boostFlag', 'boostValue', 'boostHours', 'sickChance', 'healHPDiv', 'cureInjury', 'cureSickness']
ITEM_EFFECT_ROWS = 64


def encode_item_effects(fx):
    """MOD_ITEM_FX from the items' "effect" blocks (content/items/*.json): rows {item id, the fields in ITEM_EFFECT_FIELDS order, a field left out is 0}, -1 = unused."""
    if len(fx) > ITEM_EFFECT_ROWS: raise SystemExit(f'{len(fx)} items have an effect; the executable has room for {ITEM_EFFECT_ROWS}')
    rows = []
    for i in sorted(fx, key=int):
        e = fx[i]; bad = sorted(set(e) - set(ITEM_EFFECT_FIELDS))
        if bad: raise SystemExit(f'item {i}: effect: unknown key {", ".join(bad)} (keys: {", ".join(ITEM_EFFECT_FIELDS)})')
        for k, v in e.items():
            if not isinstance(v, int) or isinstance(v, bool) or not -32768 <= v <= 32767: raise SystemExit(f'item {i}: effect.{k}: a whole number from -32768 to 32767')
        rows.append([int(i)] + [e.get(k, 0) for k in ITEM_EFFECT_FIELDS])
    rows += [[-1] + [-1] * len(ITEM_EFFECT_FIELDS)] * (ITEM_EFFECT_ROWS - len(rows))
    return b''.join(struct.pack('<%dh' % (1 + len(ITEM_EFFECT_FIELDS)), *r) for r in rows)


def encode_named(key, obj, exe):
    quiz = obj.get('quiz') if key == 'newGame' else None
    if quiz is not None:
        obj = dict(obj)
        obj.pop('quiz')
    paths = NAMED_RULES[key]; known = {re.sub(r'\[\d+\]', '', p) for p in paths if p}; seen = set()
    def walk(o, pre):
        for k, v in o.items():
            if k.startswith('_'): continue
            if isinstance(v, dict): walk(v, pre + k + '.')
            else: seen.add(pre + k)
    walk(obj, '')
    bad = sorted(seen - known)
    if bad: raise SystemExit(f'{key}: unknown key {", ".join(bad)} (keys: {", ".join(sorted(known))})')
    vals = []
    for path in paths:
        v = -1; d = _get(obj, path) if path else None
        if d is not None:
            if path in TIME_SLOTS.get(key, ()): d = duration_frames(d, f'{key}.{path}')
            elif path in REAL_MS.get(key, ()): d = real_ticks(d, f'{key}.{path}')
            elif path in EXTRA_MS.get(key, ()): d = real_ticks(d, f'{key}.{path}', True)
            wide = NAMED_FMT.get(key) == 'i'
            if not isinstance(d, int) or isinstance(d, bool) or not -(1 << 31) <= d < (1 << 31) or (not wide and not -32768 <= d <= 32767) or d == -1:
                raise SystemExit(f'{key}.{path}: a whole number (not -1: leave the key out for "does not exist")')
            lo, hi = NAMED_LIMITS.get((key, path), (-(1 << 31), (1 << 31) - 1) if wide else (-32768, 32767))
            if not lo <= d <= hi: raise SystemExit(f'{key}.{path}: {d}, from {lo} to {hi}')
            v = d
        vals.append(v)
    fmt = NAMED_FMT.get(key, "h"); n = exe.where(key)[2] // struct.calcsize(fmt)   # an executable from before a table grew
    raw = struct.pack(f'<{n}{fmt}', *(vals[:n] + [-1] * (n - len(vals))))
    if key == 'newGame' and n > 20 and quiz is not None:
        import starter_quiz
        if n != 76:
            raise SystemExit('newGame: unsupported packed quiz table size')
        raw = raw[:80] + starter_quiz.pack(dict(obj, quiz=quiz))
    return raw   # older executables hold only their original slots


TRAIN_KINDS = {'trigger': 0, 'counter': 1, 'item': 2}


TRAIN_GYMS = ['hp', 'mp', 'off', 'def', 'spd', 'brain']
TRAIN_GAIN_FIELDS = ['hp', 'mp', 'off', 'def', 'spd', 'brain', 'tired', 'energy', 'happy']
TRAIN_GAIN_ROWS = 16


def encode_train_gain(key, rows):
    """MOD_TRAIN_GAIN / MOD_TRAIN2_GAIN from training-gains.json: rows {gym, slot (a number or "any"), the six stats and tired/energy/happy}, a field left out is 0."""
    if len(rows) > TRAIN_GAIN_ROWS: raise SystemExit(f'{key}: at most {TRAIN_GAIN_ROWS} rows')
    out = []
    for i, r in enumerate(rows):
        w = f'{key}[{i}]'
        bad = sorted(set(r) - set(TRAIN_GAIN_FIELDS) - {'gym', 'slot'})
        if bad: raise SystemExit(f'{w}: unknown key {", ".join(bad)} (keys: gym, slot, {", ".join(TRAIN_GAIN_FIELDS)})')
        if r.get('gym') not in TRAIN_GYMS: raise SystemExit(f'{w}: gym: one of {", ".join(TRAIN_GYMS)}')
        slot = -2 if r.get('slot') == 'any' else r.get('slot')
        if not isinstance(slot, int) or isinstance(slot, bool): raise SystemExit(f'{w}: slot: a number or "any"')
        for f in TRAIN_GAIN_FIELDS:
            if not isinstance(r.get(f, 0), int) or isinstance(r.get(f, 0), bool): raise SystemExit(f'{w}.{f}: a whole number')
        out.append([TRAIN_GYMS.index(r['gym']), slot] + [r.get(f, 0) for f in TRAIN_GAIN_FIELDS])
    out += [[-1] * (2 + len(TRAIN_GAIN_FIELDS))] * (TRAIN_GAIN_ROWS - len(out))
    return b''.join(struct.pack('<%dh' % (2 + len(TRAIN_GAIN_FIELDS)), *r) for r in out)


def encode_training(t):
    """The three tables of trn_reward.c from content/tables/training.json's `training`."""
    bad = set(t) - {'gainTenths', 'levelTenths', 'bonuses', 'note'}
    if bad: raise SystemExit(f'training.json: unknown key {", ".join(sorted(bad))}')
    g = t.get('gainTenths', []); lv = t.get('levelTenths', []); bn = t.get('bonuses', [])
    if len(g) > 6 or any(len(r) != 5 for r in g): raise SystemExit('training.json gainTenths: up to 6 rows (one per stat), each with 5 numbers (training types 0..3, other)')
    if len(lv) > 8: raise SystemExit('training.json levelTenths: up to 8 numbers (level 0..7)')
    if len(bn) > 6: raise SystemExit('training.json bonuses: room for 6')
    num = b''.join(struct.pack('<5h', *r) for r in g) + struct.pack('<5h', *[-1] * 5) * (6 - len(g))
    level = struct.pack(f'<{len(lv)}h', *lv) + struct.pack('<h', -1) * (8 - len(lv))
    rows = b''
    for i, r in enumerate(bn):
        w = f'training.json bonuses[{i}]'
        if set(r) - {'when', 'arg', 'modes', 'multiply', 'note'} or r.get('when') not in TRAIN_KINDS or len(r.get('multiply', [])) != 2 or not r.get('modes'):
            raise SystemExit(f'{w}: {{"when": trigger|counter|item, "arg": number, "modes": [0..5], "multiply": [num, den]}}')
        rows += struct.pack('<5h', TRAIN_KINDS[r['when']], r['arg'], sum(1 << m for m in r['modes']), *r['multiply'])
    rows += struct.pack('<5h', -1, 0, 0, 0, 1) * (6 - len(bn))
    return {'trainingNum': num, 'trainingLevel': level, 'trainingBonus': rows}


EVO_STATS = ['discipline', 'happiness', 'tiredness', 'battles', 'defense', 'evoTimer', 'screen', 'scoldFlag']
EVO_MODES = {'wake': 2, 'praise': 3}
EVO_RULE = '<5h4b4(bbh)'.replace('4(bbh)', 'bbhbbhbbhbbh')           # evolution.c ModEvoRule: 30 bytes
EVO_RULE_MAX, EVO_PAIR_MAX = 10, 8

MEDAL_KINDS = {'allTriggers': (1, 2), 'wins': (2, 1), 'allCards': (3, 1), 'allMoves': (4, 1), 'stats': (5, 2), 'money': (6, 1),
               'year': (7, 1), 'allRaised': (8, 2), 'fish': (9, 1)}                      # kind id, how many numbers
MEDAL_CHECKED = {'tick': 1, 'script': 2}
MEDAL_ROW, MEDAL_MAX = '<h4bxx2i', 16                                                     # tournament.h ModMedal: 16 bytes


def encode_medals(rows):
    """tournament.h's MOD_MEDALS from content/tables/medals.json."""
    if len(rows) > MEDAL_MAX: raise SystemExit(f'medals.json: {len(rows)} rows, room for {MEDAL_MAX}')
    out = b''
    for i, r in enumerate(rows):
        w = f'medals.json medals[{i}]'
        bad = set(r) - {'medal', 'when', 'checkedBy', 'text', 'levelUp', 'note'}
        if bad: raise SystemExit(f'{w}: unknown key {", ".join(sorted(bad))}')
        k, *args = r.get('when', [None])
        if k not in MEDAL_KINDS or len(args) != MEDAL_KINDS[k][1]:
            raise SystemExit(f'{w}: when is [kind, numbers...]: ' + '; '.join(f'{n} {c} number(s)' for n, (_, c) in MEDAL_KINDS.items()))
        by = r.get('checkedBy', [])
        if not by or any(b not in MEDAL_CHECKED for b in by): raise SystemExit(f'{w}: checkedBy is a list of: {", ".join(MEDAL_CHECKED)}')
        if not isinstance(r.get('medal'), int) or not 0 <= r['medal'] < 32767: raise SystemExit(f'{w}: medal is the medal number')
        flags = sum(MEDAL_CHECKED[b] for b in by) | (4 if r.get('levelUp') else 0)
        out += struct.pack(MEDAL_ROW, r['medal'], MEDAL_KINDS[k][0], flags, r.get('text', 0), 0, *(args + [0, 0])[:2])
    return out + struct.pack(MEDAL_ROW, -1, 0, 0, 0, 0, 0, 0) * (MEDAL_MAX - len(rows))


# lists of small rows with a fixed room, empty rows -1: key -> (struct format, JSON fields, room); content/tables/evolution-rules.json
ROW_RULES = {'evolutionFresh': ('<2h', ('from', 'to'), 8), 'evolutionUltimate': ('<2h', ('from', 'to'), 8),
             'evolutionItemRules': ('<3h', ('item', 'target', 'partnerLevel'), 4),
             'tournamentRemap': ('<2h', ('from', 'to'), 4),
             'modelScale': ('<2h', ('species', 'percent'), 8), 'animatedTexture': ('<2h', ('species', 'width'), 16)}

RULE_KEYS = set(NAMED_RULES) | set(ROW_RULES) | {'evolutionRules', 'medals', 'careOverrides', 'itemEffects', 'trainGain', 'train2Gain'}      # tables the C starts empty: authored in content/tables


def encode_rule_rows(key, rows):
    fmt, fields, room = ROW_RULES[key]
    if len(rows) > room: raise SystemExit(f'{key}: {len(rows)} rows, room for {room}')
    for r in rows:
        if set(r) - set(fields) - {'note'} or any(not isinstance(r.get(f), int) for f in fields):
            raise SystemExit(f'{key}: a row is {{{", ".join(chr(34) + f + chr(34) + ": number" for f in fields)}}}')
    return b''.join(struct.pack(fmt, *[r[f] for f in fields]) for r in rows) + struct.pack(fmt, *[-1] * len(fields)) * (room - len(rows))


def encode_evo_rules(rules):
    """evolution.c's MOD_EVO_RULES from the list of content/tables/evolution-rules.json `rules`."""
    if len(rules) > EVO_RULE_MAX: raise SystemExit(f'evolution-rules.json rules: {len(rules)} rules, room for {EVO_RULE_MAX}')
    out = b''
    for i, r in enumerate(rules):
        w = f'evolution-rules.json rules[{i}]'
        bad = set(r) - {'mode', 'chance', 'from', 'level', 'when', 'target', 'clearsScoldFlag', 'note'}
        if bad: raise SystemExit(f'{w}: unknown key {", ".join(sorted(bad))}')
        if r.get('mode') not in EVO_MODES: raise SystemExit(f'{w}: mode is {" or ".join(EVO_MODES)}')
        frm = list(r.get('from', []))
        if len(frm) > 4: raise SystemExit(f'{w}: from names at most 4 species (leave it out for any)')
        when = r.get('when', [])
        if len(when) > 4: raise SystemExit(f'{w}: when has at most 4 conditions')
        cond = []
        for c in when:
            if len(c) != 3 or c[0] not in EVO_STATS or c[1] not in ('==', '>='):
                raise SystemExit(f'{w}: a condition is [stat, "==" or ">=", number]; stats: {", ".join(EVO_STATS)}')
            cond.append((EVO_STATS.index(c[0]), ('==', '>=').index(c[1]), c[2]))
        cond += [(-1, 0, 0)] * (4 - len(cond))
        ch = r.get('chance', 100)
        if not 0 <= ch <= 100: raise SystemExit(f'{w}: chance is 0..100 (percent)')
        out += struct.pack(EVO_RULE, r['target'], *(frm + [-1] * (4 - len(frm))), EVO_MODES[r['mode']], ch, r.get('level', -1),
                           1 if r.get('clearsScoldFlag') else 0, *[x for c in cond for x in c])
    return out + struct.pack(EVO_RULE, -1, -1, -1, -1, -1, 0, 0, -1, 0, *([-1, 0, 0] * 4)) * (EVO_RULE_MAX - len(rules))


DONOR_FLAGS = {'same_rig': 1, 'fallback': 2, 'always': 4}
DONOR_ENTRY, DONOR_ORIGIN = '<13h', '<8h'                   # efe.c ModTechDonor, ModTechOrigin


def decode_donors(exe):
    """content/tables/effect-donors.json's list from the three flat tables of efe.c."""
    ents, ors, bns = exe.raw('donorEntries'), exe.raw('donorOrigins'), exe.raw('donorBones')
    out = []
    for i in range(len(ents) // struct.calcsize(DONOR_ENTRY)):
        t, donor, num, den, fl, o0, on, b0, bn, *fb = struct.unpack_from(DONOR_ENTRY, ents, struct.calcsize(DONOR_ENTRY) * i)
        if t < 0: continue
        d = {'species': t, 'donor': donor, 'scale': [num, den], 'flags': [n for n, b in DONOR_FLAGS.items() if fl & b]}
        if any(fb): d['fallback'] = fb
        if on:
            d['origins'] = [{'from': list(struct.unpack_from('<4h', ors, 16 * k)), 'to': list(struct.unpack_from('<4h', ors, 16 * k + 8))}
                            for k in range(o0, o0 + on)]
        if bn: d['bones'] = list(struct.unpack_from(f'<{bn}b', bns, b0))
        out.append(d)
    return out


def encode_donors(donors, exe):
    """The three flat tables of efe.c from the list (pools in entry order); the entries and pools have fixed capacity."""
    ne = exe.syms['donorEntries'][1] // struct.calcsize(DONOR_ENTRY)
    no = exe.syms['donorOrigins'][1] // 16; nb = exe.syms['donorBones'][1]
    ents, ors, bns = [], [], []
    for i, d in enumerate(donors):
        w = f'effect-donors.json entry {i}'
        bad = [k for k in d if k not in ('species', 'donor', 'scale', 'flags', 'fallback', 'origins', 'bones', 'note')]
        if bad: raise SystemExit(f'{w}: unknown key {", ".join(bad)}')
        if any(f not in DONOR_FLAGS for f in d.get('flags', [])): raise SystemExit(f'{w}: flags are {", ".join(DONOR_FLAGS)}')
        for k, n in (('scale', 2), ('fallback', 4)):
            if k in d and len(d[k]) != n: raise SystemExit(f'{w}: {k} has {n} numbers')
        if not d['scale'][1]: raise SystemExit(f'{w}: scale[1] is 0')
        o = d.get('origins', []); b = d.get('bones', [])
        for x in o:
            if len(x['from']) != 4 or len(x['to']) != 4: raise SystemExit(f'{w}: an origin is {{"from": [bone, x, y, z], "to": [bone, x, y, z]}}')
        ents.append(struct.pack(DONOR_ENTRY, d['species'], d['donor'], *d['scale'], sum(DONOR_FLAGS[f] for f in d.get('flags', [])),
                                len(ors), len(o), len(bns), len(b), *d.get('fallback', [0, 0, 0, 0])))
        ors += [struct.pack(DONOR_ORIGIN, *x['from'], *x['to']) for x in o]; bns += b
    if len(ents) > ne or len(ors) > no or len(bns) > nb:
        raise SystemExit(f'effect-donors.json: {len(ents)} entries, {len(ors)} origins, {len(bns)} bones; the executable has room for {ne}, {no}, {nb}')
    pad = struct.pack(DONOR_ENTRY, -1, *[0] * 12)
    return {'donorEntries': b''.join(ents) + pad * (ne - len(ents)),
            'donorOrigins': b''.join(ors) + bytes(16 * (no - len(ors))),
            'donorBones': struct.pack(f'<{len(bns)}b', *bns) + bytes(nb - len(bns))}


def decode_species_tables(exe, sp):
    """The voice, effect, training, music and birth rows of each species (tools/species.py makes files of them)."""
    for t, v in enumerate(exe.raw('vlall')): sp(t)['vlall'] = v
    for t, v in enumerate(exe.raw('vball')): sp(t)['vball'] = v
    raw = exe.raw('originalTypes')
    for t, v in enumerate(struct.unpack(f'<{len(raw) // 2}h', raw)): sp(t)['originalType'] = v
    for key in ('trainingAnims', 'training2Anims'):
        raw = exe.raw(key)
        for t in range(len(raw) // 2): sp(t)[key] = list(struct.unpack_from('<2b', raw, 2 * t))
    if exe.has('battleMusic'):
        raw = exe.raw('battleMusic')
        if exe.compiled:
            for t, v in enumerate(raw): sp(t)['battleMusic'] = v
        else:                             # ENEMY_MUSIC_MAPPING: what the game plays (btl.c), every other type track 1
            for t in range(NUM_ORIGINAL):
                sp(t)['battleMusic'] = raw[t - MUSIC_FIRST] if MUSIC_FIRST <= t < MUSIC_FIRST + MUSIC_LIVE else 1
    if exe.has('reincarnation'):
        raw = exe.raw('reincarnation')
        for i in range(len(raw) // 14):
            t, *stats = struct.unpack_from('<7h', raw, 14 * i)
            if t >= 0: sp(t)['reincarnation'] = stats
    if exe.has('newGameTechniques'):
        raw = exe.raw('newGameTechniques')
        for i in range(len(raw) // 4):
            t, tech, anim = struct.unpack_from('<hBB', raw, 4 * i)
            if t >= 0: sp(t)['newGameTechnique'] = (tech, anim)


def encode_species_tables(S, exe, out):
    """The per-species tables of exe's layout from the species rows S ({"t": rows}, tools/species.table_rows)."""
    size = lambda t: exe.syms[t][1]
    def row(t, key):
        r = S.get(str(t), {}).get(key)
        if r is None: raise SystemExit(f'species {t}: no "{key}" row (the table has {t + 1} or more rows)')
        return r
    out['vlall'] = bytes(row(t, 'vlall') for t in range(size('vlall')))
    out['vball'] = bytes(row(t, 'vball') for t in range(size('vball')))
    out['originalTypes'] = struct.pack(f'<{size("originalTypes") // 2}h', *(row(t, 'originalType') for t in range(size('originalTypes') // 2)))
    for key in ('trainingAnims', 'training2Anims'):
        out[key] = b''.join(struct.pack('<2b', *row(t, key)) for t in range(size(key) // 2))
    if exe.has('battleMusic'):
        if exe.compiled:
            out['battleMusic'] = bytes(row(t, 'battleMusic') for t in range(size('battleMusic')))
        else:
            out['battleMusic'] = bytes(row(MUSIC_FIRST + i, 'battleMusic') if i < MUSIC_LIVE else 0 for i in range(size('battleMusic')))
    for key, fmt, n, field in (('reincarnation', '<7h', 14, 'reincarnation'), ('newGameTechniques', '<hBB', 4, 'newGameTechnique')):
        if not exe.has(key): continue
        rows = [(int(t), r[field]) for t, r in sorted(S.items(), key=lambda x: int(x[0])) if r.get(field)]
        if len(rows) > size(key) // n:
            raise SystemExit(f'{len(rows)} species have "{field}": the executable\'s table has {size(key) // n} rows')
        blob = b''.join(struct.pack(fmt, t, *v) for t, v in rows)
        blob += b''.join(struct.pack(fmt, -1, *([0] * (6 if n == 14 else 2))) for _ in range(size(key) // n - len(rows)))
        out[key] = blob


def encode(doc, exe):
    """{table: bytes} of a full document, in the layout (row counts, widths) of exe."""
    out = {}; S = doc['species']
    def rows(key, fields, size, first=0):
        n = struct.calcsize(SP._fmt(fields)); blob = b''
        for t in range(first, first + size // n):
            r = S.get(str(t), {}).get(key)
            if r is None: raise SystemExit(f'species {t}: no "{key}" (the table {key} has {size // n} rows)')
            blob += SP.pack(fields, r)
        return blob
    size = lambda t: exe.syms[t][1]
    out['para'] = rows('para', SP.PARA_FIELDS, size('para'))
    out['raise'] = rows('raise', SP.RAISE_FIELDS, size('raise'))
    out['evoReqs'] = rows('evoReqs', SP.REQ_FIELDS, size('evoReqs'))
    out['evoGains'] = rows('evoGains', SP.GAIN_FIELDS, size('evoGains'))
    w = 1 if size('evoPaths') == 62 * 11 else 2; blob = b''
    for i in range(size('evoPaths') // (11 * w)):
        p = S[str(i + 1)]['evoPaths']
        if len(p['from']) > 5 or len(p['to']) > 6: raise SystemExit(f'species {i + 1}: evoPaths has at most 5 from, 6 to')
        p = {'from': (list(p['from']) + [-1] * 5)[:5], 'to': (list(p['to']) + [-1] * 6)[:6]}   # shorter lists: -1 = empty
        if w == 1 and any(not -128 <= x < 128 for x in p['from'] + p['to']):
            raise SystemExit(f'species {i + 1}: evoPaths id beyond 127 in an executable with 8-bit paths')
        blob += struct.pack('<11' + 'bh'[w - 1], *p['from'], *p['to'])
    out['evoPaths'] = blob
    vals = []
    for i in range(size('itemTakeDistance')):
        t = i + 1                             # by type - 1: the mod's last row is type 180, no species (written 0)
        vals.append(S[str(t)]['itemTakeDistance'] if t < NUM_ORIGINAL else 0)
    out['itemTakeDistance'] = struct.pack(f'<{len(vals)}b', *vals)
    encode_species_tables(S, exe, out)
    T = doc['techniques']
    out['techniques'] = b''.join(SP.pack(MOVE_FIELDS, T[str(i)]) for i in range(size('techniques') // 16))
    out['learnChances'] = bytes(sum((T[str(i)]['learnChances'] for i in range(size('learnChances') // 3)), []))
    out['typeFactors'] = bytes(sum(doc['typeFactors'], []))
    out['evolutionItems'] = bytes(doc['evolutionItems'][str(0x47 + i)] for i in range(size('evolutionItems')))
    out['joinChances'] = bytes(sum(doc['joinChances'], []))
    out['items'] = b''.join(SP.pack(ITEM_FIELDS, doc['items'][str(i)]) for i in range(size('items') // 32))
    tr = doc['tournaments']
    out['schedule'] = bytes(sum(tr['schedule'], []))
    out['opponentBaseStats'] = struct.pack('<24h', *tr['opponentBaseStats'])
    out['winChances'] = bytes(sum(tr['winChances'], []))
    for suffix, key in (('', 'brainTraining'),):
        bt = doc.get(key) or doc['brainTraining']
        out['brainTechs' + suffix] = bytes(sum((bt['techniques'][e] for e in ELEMENTS), []))
        out['brainWeights' + suffix] = struct.pack('<24b', *sum(bt['weights'], []))
    if 'screens' in doc:
        blob = b''
        for i in range(size('screens') // 16):
            e = doc['screens'][str(i)]
            nb = bytes(e['fileBytes']) if e.get('fileBytes') and bytes(e['fileBytes']).rstrip(b'\0').decode('latin-1') == e['file'] \
                else e['file'].encode('latin-1').ljust(10, b'\0')
            blob += nb[:10] + struct.pack('<bbBbbB', e['tims8'], e['tims4'], e['flags'], e['doors'], e['toilet'], e['caption'])
        out['screens'] = blob
    if 'doors' in doc:
        out['doors'] = b''.join(struct.pack('<6B', *[d[0] for d in g]) + struct.pack('<24h', *[d[j] for j in range(1, 5) for d in g])
                                for g in doc['doors'])
    if 'toilets' in doc: out['toilets'] = b''.join(struct.pack('<4h', *t) for t in doc['toilets'])
    for k, _, _, fmt, fields in SMALL_TABLES:
        if k in doc and (k not in OPTIONAL or exe.has(k)):
            kept = [struct.unpack_from(fmt, exe.raw(k), struct.calcsize(fmt) * i) for i in range(len(doc[k]))] if k in KEEP else None
            out[k] = b''.join(struct.pack(fmt, *([r[f] if f not in KEEP.get(k, ()) else kept[i][fields.index(f)] for f in fields] if fields
                                                 else (r if isinstance(r, list) else [r])))
                              for i, r in enumerate(doc[k]))
    if 'effectDonors' in doc and exe.has('donorEntries'): out.update(encode_donors(doc['effectDonors'], exe))
    if 'itemEffects' in doc and exe.has('itemEffects'):
        out['itemEffects'] = encode_item_effects(doc['itemEffects'])
    if 'careOverrides' in doc and exe.has('careOverrides'):
        out['careOverrides'] = b''.join(struct.pack('<3h', *r) for r in doc['careOverrides']) + struct.pack('<3h', -1, -1, -1) * (CARE_OVERRIDE_MAX - len(doc['careOverrides']))
    for k in NAMED_RULES:
        if k in doc and exe.has(k): out[k] = encode_named(k, doc[k], exe)
    for k in ROW_RULES:
        if k in doc and exe.has(k): out[k] = encode_rule_rows(k, doc[k])
    if 'training' in doc and exe.has('trainingNum'): out.update(encode_training(doc['training']))
    if 'training2' in doc and exe.has('train2Num'):
        t2 = encode_training(doc['training2'])
        out.update({'train2Num': t2['trainingNum'], 'train2Level': t2['trainingLevel'], 'train2Bonus': t2['trainingBonus']})
    for k in ('trainGain', 'train2Gain'):
        if k in doc and exe.has(k): out[k] = encode_train_gain(k, doc[k])
    if 'medals' in doc and exe.has('medals'): out['medals'] = encode_medals(doc['medals'])
    if 'evolutionRules' in doc and exe.has('evolutionRules'): out['evolutionRules'] = encode_evo_rules(doc['evolutionRules'])
    for t, b in out.items():
        if len(b) != size(t): raise SystemExit(f'{t}: {len(b)} bytes for a {size(t)}-byte table')
    return out


# ------------------------------------------------------------------ wild Digimon of the .MAP files
def map_files():
    return sorted(os.path.relpath(p, EXTRACTED) for p in glob.glob(os.path.join(EXTRACTED, 'MAP', '*', '*.MAP')))


def map_wild(data):
    """[(file offset of the 33 s16, fields)] of the placed Digimon of a .MAP (dwmap.MapFile's reading)."""
    import dwmap
    m = dwmap.MapFile(data)
    n = struct.unpack_from('<I', data)[0] // 4
    ent = struct.unpack_from(f'<{n}I', data)[n - 2]
    out = []; p = ent + 122
    for d in m.digimon:
        out.append((p, d)); p += 66 + 2 + 16 + 6 * len(d['waypoints'])
    return out


def wild_entry(d):
    e = {k: d[k] for k in WILD_FIELDS}
    e['moves'] = [d[f'move{i}'] for i in range(4)]; e['prios'] = [d[f'prio{i}'] for i in range(4)]
    e['_type'] = d['type']
    return e


def decode_maps(sources=None):
    out = {}
    for rel in map_files():
        data = open((sources or {}).get(rel) or os.path.join(EXTRACTED, rel), 'rb').read()
        w = map_wild(data)
        if w: out[rel] = {str(i): wild_entry(d) for i, (_, d) in enumerate(w)}
    return out


# ------------------------------------------------------------------ layers
def merge(base, over, path=''):
    """base with over's values (dicts recursively; lists and numbers replaced); comment keys skipped."""
    if not isinstance(over, dict) or not isinstance(base, dict):
        return json.loads(json.dumps(over))
    out = dict(base)
    for k, v in over.items():
        if str(k).startswith('_'): continue
        out[k] = merge(base[k], v, f'{path}.{k}') if k in base and isinstance(v, dict) else json.loads(json.dumps(v))
    return out


def diff(base, new):
    """The sparse document that turns base into new (lists whole)."""
    if isinstance(base, dict) and isinstance(new, dict):
        out = {}
        for k, v in new.items():
            if k not in base: out[k] = v
            else:
                d = diff(base[k], v)
                if d is not None: out[k] = d
        return out or None
    return None if base == new else new


def load_overrides(content=CONTENT):
    """The override files (top level of content/balance, sorted), merged; a field set by two files is an error."""
    out, owner = {}, {}
    for p in sorted(glob.glob(os.path.join(content, '*.json'))):
        d = json.load(open(p))
        def walk(o, path):
            for k, v in o.items():
                if str(k).startswith('_'): continue
                q = path + (k,)
                if isinstance(v, dict) and not (len(q) == 3 and q[0] == 'maps'): walk(v, q)
                elif q in owner: raise SystemExit(f'{p}: {".".join(q)} is also set by {owner[q]}')
                else: owner[q] = os.path.relpath(p, ROOT)
        walk(d, ())
        out = merge(out, _strip(d))
    return out


def load_engine():
    return _strip(json.load(open(ENGINE))) if os.path.exists(ENGINE) else {}


def original_doc():
    return decode(Exe(EXTRACTED))


# ------------------------------------------------------------------ validation
RANGES = {'b': (-128, 127), 'B': (0, 255), 'h': (-32768, 32767), 'H': (0, 65535), 'i': (-2 ** 31, 2 ** 31 - 1)}


def _check_fields(errs, where, fields, d, skip=()):
    known = {n: f for n, f in fields if f != 'x'}
    for k, v in d.items():
        if k in skip: continue
        if k not in known: errs.append(f'{where}.{k}: unknown field ({", ".join(known)})'); continue
        f = known[k]; n = int(f[:-1]) if f[:-1].isdigit() else 1
        if f.endswith('s'):
            if not isinstance(v, str) or len(v.encode()) >= n: errs.append(f'{where}.{k}: a text of at most {n - 1} characters')
            continue
        vals = v if n > 1 else [v]
        if n > 1 and (not isinstance(v, list) or len(v) != n): errs.append(f'{where}.{k}: a list of {n} numbers'); continue
        lo, hi = RANGES[f[-1]]
        for x in vals:
            if not isinstance(x, int) or not lo <= x <= hi: errs.append(f'{where}.{k}: {x} is not in {lo}..{hi}')


def validate(over, base, new_species):
    """Errors of an override document against the merged base (original + engine) and the species of content/species."""
    errs = []; S = base['species']; T = base['techniques']
    known_species = {int(t) for t in S} | set(new_species)
    def species_ref(where, t, allow_none=True):
        if allow_none and t in (-1, 255): return
        if t not in known_species: errs.append(f'{where}: species {t} does not exist')
    def tech_ref(where, m):
        if m != 0xFF and str(m) not in T: errs.append(f'{where}: technique {m} does not exist (0..{len(T) - 1}, 255 none)')
    top = {'species', 'techniques', 'typeFactors', 'evolutionItems', 'joinChances', 'items', 'tournaments',
           'brainTraining', 'maps', 'unusedRows'}
    for k in over:
        if k not in top: errs.append(f'{k}: unknown section ({", ".join(sorted(top))})')
    if 'species' in over:
        errs.append('species: species are not balance overrides: their values are in content/species/<id>-<name>.json '
                    '(docs/mods/species.md)')
    for t, o in {}.items():
        w = f'species.{t}'
        if not t.lstrip('-').isdigit(): errs.append(f'{w}: the key is the species id'); continue
        ti = int(t)
        if ti not in known_species: errs.append(f'{w}: no such species'); continue
        have = S.get(t, {})
        for k, v in o.items():
            wk = f'{w}.{k}'
            if ti < NUM_ORIGINAL and k not in have:
                errs.append(f'{wk}: the executable has no {k} row for species {t}'); continue
            if k == 'para':
                _check_fields(errs, wk, SP.PARA_FIELDS, v)
                if 'boneCount' in v: errs.append(f'{wk}.boneCount: follows the model, not balance')
                for m in v.get('moves', []): tech_ref(f'{wk}.moves', m)
                for e in v.get('special', []):
                    if e != 0xFF and not 0 <= e < 7: errs.append(f'{wk}.special: {e} is not an element (0..6, 255)')
                if 'dropItem' in v and v['dropItem'] != 0xFF and str(v['dropItem']) not in base['items']:
                    errs.append(f'{wk}.dropItem: item {v["dropItem"]} does not exist')
                if 'dropChance' in v and not 0 <= v['dropChance'] <= 100: errs.append(f'{wk}.dropChance: a percentage')
                if 'level' in v and not 0 <= v['level'] <= 6: errs.append(f'{wk}.level: 0..6')
            elif k == 'raise': _check_fields(errs, wk, SP.RAISE_FIELDS, v)
            elif k == 'evoReqs':
                _check_fields(errs, wk, SP.REQ_FIELDS, v)
                if 'digimon' in v: species_ref(f'{wk}.digimon', v['digimon'])
            elif k == 'evoGains':
                _check_fields(errs, wk, SP.GAIN_FIELDS, v)
            elif k == 'evoPaths':
                for side, n in (('from', 5), ('to', 6)):
                    if side not in v: continue
                    if not isinstance(v[side], list) or len(v[side]) > n: errs.append(f'{wk}.{side}: at most {n} species'); continue
                    for x in v[side]: species_ref(f'{wk}.{side}', x)
                for x in set(v) - {'from', 'to'}: errs.append(f'{wk}.{x}: unknown (from, to)')
            elif k == 'itemTakeDistance':
                if not isinstance(v, int) or not -128 <= v <= 127: errs.append(f'{wk}: -128..127')
            else: errs.append(f'{wk}: unknown key (para, raise, evoReqs, evoGains, evoPaths, itemTakeDistance)')
    for i, o in over.get('techniques', {}).items():
        w = f'techniques.{i}'
        if i not in T: errs.append(f'{w}: no such technique (0..{len(T) - 1})'); continue
        _check_fields(errs, w, MOVE_FIELDS, o, skip=('learnChances',))
        if 'learnChances' in o:
            if 'learnChances' not in T[i]: errs.append(f'{w}.learnChances: only techniques 0..57 are learnable')
            elif not (isinstance(o['learnChances'], list) and len(o['learnChances']) == 3 and all(0 <= x <= 100 for x in o['learnChances'])):
                errs.append(f'{w}.learnChances: three percentages (main, second, third element)')
        if o.get('special', 0) != 0xFF and not 0 <= o.get('special', 0) < 7: errs.append(f'{w}.special: element 0..6 or 255')
        if not 0 <= o.get('status', 0) <= 4: errs.append(f'{w}.status: 0 none, 1 poison, 2 confusion, 3 stun, 4 flatten')
        if not 0 <= o.get('range', 1) <= 4: errs.append(f'{w}.range: 1 melee, 2 ranged, 3 area, 4 self')
        for k in ('accuracy', 'statusChance'):
            if k in o and not 0 <= o[k] <= 100: errs.append(f'{w}.{k}: a percentage')
    for it, s in over.get('evolutionItems', {}).items():
        if it not in base['evolutionItems']: errs.append(f'evolutionItems.{it}: items 71..114 (0x47..0x72)')
        species_ref(f'evolutionItems.{it}', s, allow_none=False)
    for it, o in over.get('items', {}).items():
        if it not in base['items']: errs.append(f'items.{it}: no such item (0..127)')
        else: _check_fields(errs, f'items.{it}', ITEM_FIELDS, o)
    def grid(where, v, rows, cols, lo=0, hi=255):
        if not (isinstance(v, list) and len(v) == rows and all(isinstance(r, list) and len(r) == cols for r in v)):
            errs.append(f'{where}: {rows} rows of {cols}'); return
        for r in v:
            for x in r:
                if not isinstance(x, int) or not lo <= x <= hi: errs.append(f'{where}: {x} not in {lo}..{hi}')
    if 'typeFactors' in over: grid('typeFactors', over['typeFactors'], 7, 7)
    if 'joinChances' in over: grid('joinChances', over['joinChances'], 4, 3)
    tr = over.get('tournaments', {})
    if 'schedule' in tr: grid('tournaments.schedule', tr['schedule'], 30, 6)
    if 'winChances' in tr: grid('tournaments.winChances', tr['winChances'], 4, 3, 0, 100)
    if 'opponentBaseStats' in tr and (len(tr['opponentBaseStats']) != 24 or not all(0 <= x <= 32767 for x in tr['opponentBaseStats'])):
        errs.append('tournaments.opponentBaseStats: 24 values 0..32767')
    for k in set(tr) - {'schedule', 'winChances', 'opponentBaseStats'}: errs.append(f'tournaments.{k}: unknown')
    for key in ('brainTraining',):
        bt = over.get(key, {})
        for e, lst in bt.get('techniques', {}).items():
            if e not in ELEMENTS: errs.append(f'{key}.techniques.{e}: elements {", ".join(ELEMENTS)}'); continue
            if len(lst) != 8: errs.append(f'{key}.techniques.{e}: 8 techniques')
            for m in lst: tech_ref(f'{key}.techniques.{e}', m)
        if 'weights' in bt: grid(f'{key}.weights', bt['weights'], 8, 3, -128, 127)
    if over.get('maps'):          # retired 2026-10-15: the placed Digimon are content/maps/<FILE>.json (tools/content.py)
        errs.append('maps: the placed Digimon are content/maps/<FILE>.json now (a stat: nothing, "+200" or a number; '
                    'docs/mods/data-sources.md "Maps"), not a balance override')
    return errs


# ------------------------------------------------------------------ annotations (comments for the dumps)
def annotate(doc):
    S = doc.get('species', {}); names = {}
    for t, s in S.items():
        if 'para' in s: names[int(t)] = s['para'].get('name') or ''
    tech = {}
    p = os.path.join(ROOT, 'docs/data/techs.csv')
    if os.path.exists(p):
        for line in open(p).read().splitlines()[1:]:
            i, _, n = line.partition(','); tech[int(i)] = n
    nm = lambda t: names.get(t, '') if t not in (-1, 255) else None
    for t, s in S.items():
        s['_name'] = names.get(int(t), '')
        if 'para' in s: s['_moves'] = [tech.get(m) for m in s['para']['moves'] if m != 0xFF]
        if 'evoPaths' in s: s['_evolvesTo'] = [nm(x) for x in s['evoPaths']['to'] if x != -1]
    for i, m in doc.get('techniques', {}).items():
        m['_name'] = tech.get(int(i), ''); m['_mp'] = m['mpCost'] * 3
    for rel, slots in doc.get('maps', {}).items():
        for e in slots.values(): e['_name'] = names.get(e.get('_type'), '')
    return doc


def ordered(doc):
    """Comment keys first in every object (readable dumps)."""
    if isinstance(doc, dict):
        ks = sorted(doc, key=lambda k: (not str(k).startswith('_'),))
        return {k: ordered(doc[k]) for k in ks}
    if isinstance(doc, list): return [ordered(v) for v in doc]
    return doc


def write_json(path, doc):
    os.makedirs(os.path.dirname(path) or '.', exist_ok=True)
    s = json.dumps(ordered(doc), indent=1)
    s = re.sub(r'\[\s+([^\[\]{}]*?)\s+\]', lambda m: '[' + re.sub(r'\s+', ' ', m.group(1)) + ']', s)   # short lists on one line
    open(path, 'w').write(s + '\n')


# ------------------------------------------------------------------ commands
def exe_dir(a):
    return a.exe_dir or DEFAULT_EXE_DIR


def zero_row(fields):
    return {n: ('' if f.endswith('s') else [0] * int(f[:-1]) if f[:-1].isdigit() else 0) for n, f in fields if f != 'x'}


EVOLUTION_KEYS = ('evoReqs', 'evoGains', 'evoPaths')     # the species rows that stay in this layer (until the evolution design)


def pad_rows(doc, exe):
    """Rows the executable has and the original does not (the mod's 180-row evolution tables) start as zeros,
    as a C array's rows without an initializer."""
    S = doc['species']; size = lambda t: exe.syms[t][1]
    for key, fields in (('evoReqs', SP.REQ_FIELDS), ('evoGains', SP.GAIN_FIELDS)):
        for t in range(size(key) // struct.calcsize(SP._fmt(fields))):
            S.setdefault(str(t), {}).setdefault(key, zero_row(fields))
    return doc


def species_rows(exe):
    """{"t": rows} of species 0..179 for exe's tables: the files of content/species (a compiled build), or the files
    `species.py extract` makes from the disc (the original executable)."""
    if exe.compiled:
        files = {t: s for t, s in SP.load_content().items() if t < NUM_ORIGINAL}
    else:
        files = {t: json.loads(SP.dumps(s)) for t, s in SP.files_from_exe(exe.folder).items()}   # through the text
    out = {}
    for t, s in sorted(files.items()):
        if SP.is_record_original(s):
            # a record original (docs/mods/species.md): DIGI.DAT carries the file's values; the executable keeps the C's
            # rows (the disc's species), which the game uses on a disc that does not carry it. The name is the file's
            # (a renamed record original is named alike with or without its record)
            rows = SP.table_rows(s); c = c_rows(exe)[str(t)]
            out[str(t)] = dict(c, para=dict(c['para'], name=rows['para']['name']))
        else:
            out[str(t)] = SP.table_rows(s)
    if exe.compiled:                                     # an id without a file: the species does not exist (zero rows)
        for t in range(NUM_ORIGINAL):
            if t not in files:
                a = SP.absent_rows(t)
                out[str(t)] = {k: a[k] for k in SP.TABLE_KEYS}
    return out


_C_ROWS = {}


def c_rows(exe):
    """{"t": rows} of the per-species tables as exe holds them (TABLE_KEYS), for the record originals."""
    if exe.folder not in _C_ROWS:
        d = decode(exe)['species']
        _C_ROWS[exe.folder] = {t: {k: r.get(k) for k in SP.TABLE_KEYS} for t, r in d.items()}
    return _C_ROWS[exe.folder]


CARE_OVERRIDE_MAX = 192             # rows of MOD_CARE_SPECIES (level.h MOD_CARE_OVERRIDE_MAX)


def care_overrides(files, rules):
    """The rows [species, slot, value] of the species files' "care" (same keys as content/tables/care-rules.json's careRules), resolved against
    the global values `rules`. A value is a whole number (absolute), "+n" / "-n" (the global value plus or minus n), "+n%" / "-n%" (the
    global value changed by n percent, rounded to the nearest) or null (the rule does not exist for that species). A relative value needs a
    global one to start from."""
    paths = NAMED_RULES['careRules']; index = {p: i for i, p in enumerate(paths) if p}; rows = []
    for t in sorted(files):
        care = files[t].get('care')
        if care is None: continue
        flat = {}
        def walk(o, pre):
            if not isinstance(o, dict): raise SystemExit(f'species {t}: care: an object of rule groups (keys: {", ".join(sorted(index))})')
            for k, v in o.items():
                if isinstance(v, dict): walk(v, pre + k + '.')
                else: flat[pre + k] = v
        walk(care, '')
        for path, v in flat.items():
            where = f'species {t}: care.{path}'
            if path not in index: raise SystemExit(f'{where}: unknown rule (keys: {", ".join(sorted(index))})')
            glob = _get(rules, path); tm = path in TIME_SLOTS['careRules']
            if glob is not None and tm: glob = duration_frames(glob, f'content/tables/care-rules.json {path}')
            if v is None: val = -1
            elif isinstance(v, bool): raise SystemExit(f'{where}: a whole number, "+n", "-n", "+n%", "-n%" or null')
            elif isinstance(v, int):
                if v == -1: raise SystemExit(f'{where}: use null for "this rule does not exist for the species"')
                val = duration_frames(v, where) if tm else v
            elif isinstance(v, str):
                m = re.fullmatch(r'([+-])(.+?)(%?)', v)
                if not m:
                    if not tm: raise SystemExit(f'{where}: "{v}" is not "+n", "-n", "+n%" or "-n%"')
                    val = duration_frames(v, where)
                else:
                    if glob is None: raise SystemExit(f'{where}: "{v}" is relative to content/tables/care-rules.json, which has no {path}')
                    sign = 1 if m.group(1) == '+' else -1
                    if m.group(3):
                        if not m.group(2).isdigit(): raise SystemExit(f'{where}: "{v}" is not "+n%" or "-n%"')
                        q = glob * (100 + sign * int(m.group(2))); val = (abs(q) + 50) // 100 * (1 if q >= 0 else -1)
                    elif tm: val = glob + sign * duration_frames(m.group(2), where)
                    elif m.group(2).isdigit(): val = glob + sign * int(m.group(2))
                    else: raise SystemExit(f'{where}: "{v}" is not "+n", "-n", "+n%" or "-n%"')
            else: raise SystemExit(f'{where}: a whole number, "+n", "-n", "+n%", "-n%" or null')
            low = -32768 if path.endswith('.min') else 0         # only a lower bound (limit.*.min) may be negative
            if val != -1 and not low <= val <= 32767: raise SystemExit(f'{where}: resolves to {val}; a rule value is {low}..32767')
            if val == -1 and v is not None: raise SystemExit(f'{where}: resolves to -1, which means "does not exist": use null')
            rows.append([t, index[path], val])
    if len(rows) > CARE_OVERRIDE_MAX: raise SystemExit(f'the species files override {len(rows)} care values; the executable has room for {CARE_OVERRIDE_MAX}')
    return rows


def content_layer(base):
    """The committed JSON over a document (docs/mods/data-sources.md): the evolution rows of the species of the
    executable's tables (their files, since 2026-10-15) and the techniques, items and small tables of content/
    (tools/content.py: complete, they replace the disc's or the executable's values)."""
    files = SP.load_content()
    for t, s in files.items():
        # Record originals <= 62 still use EVOLUTION_PATHS, unlike their other
        # partner rows. Seed it from the record before archive links fill it.
        if 1 <= t <= 62 and SP.is_record_original(s) and 'evolution' in s:
            base['species'].setdefault(str(t), {})['evoPaths'] = {
                k: (list(s['evolution'].get(k, [])) + [-1] * n)[:n]
                for k, n in (('from', 5), ('to', 6))}
        if t < NUM_ORIGINAL and not SP.is_record_original(s) and 'evolution' in s:
            r, g, paths = SP.disc_evolution_rows(t, s['evolution'])
            b = base['species'].setdefault(str(t), {})
            b['evoReqs'] = r; b['evoGains'] = g
            if paths is not None: b['evoPaths'] = paths
    if any(t < NUM_ORIGINAL for t in files):            # an id without a file: no evolution row, in no path list
        gone = {t for t in range(NUM_ORIGINAL) if t not in files}
        for t in gone:
            a = SP.absent_rows(t); b = base['species'].setdefault(str(t), {})
            b['evoReqs'] = a['evoReqs']; b['evoGains'] = a['evoGains']
            if a['evoPaths'] is not None: b['evoPaths'] = a['evoPaths']
        for b in base['species'].values():
            if b.get('evoPaths'):
                b['evoPaths'] = {k: [-1 if x in gone else x for x in v] for k, v in b['evoPaths'].items()}
    import content
    base = merge(base, content.doc())
    base['careOverrides'] = care_overrides(files, base.get('careRules', {}))
    if any(t < NUM_ORIGINAL for t in files):            # an evolution item of a species that does not exist gives nothing
        for it, t in base.get('evolutionItems', {}).items():
            if t < NUM_ORIGINAL and t not in files: base['evolutionItems'][it] = 0
    return base


def with_species_rows(base, exe):
    """base with the species rows of the species files (all but the evolution rows: content_layer)."""
    for t, rows in species_rows(exe).items():
        b = base['species'].setdefault(t, {})
        for k in [k for k in b if k not in EVOLUTION_KEYS]: del b[k]
        b.update(json.loads(json.dumps(rows)))
    return base


def layered(exe, content=True):
    """What the tables of exe must hold: the species rows of the species files, the evolution rows and the other
    tables of the original + the engine layer (which only applies to a compiled executable), then the committed JSON
    (content_layer). content=False: without the JSON's evolution rows and tables (what the C should hold: the check for a
    C patch that changed a table after the last sync)."""
    base = json.loads(json.dumps(original_doc()))
    if exe.compiled: base = merge(pad_rows(base, exe), load_engine())
    base = with_species_rows(base, exe)
    if not content: return base
    base = content_layer(base)
    if exe.compiled: keep_text_names(base, exe)
    return base


def keep_text_names(doc, exe):
    """An item's shown name is text (docs/mods/data-sources.md): the executable's ITEM_PARA name, which gen_text wrote
    from the text source (TEXT=ours: our translation, main.ITEM_NAMES), stays; content/items' `name` names the item for
    the tools. An item without a file keeps its empty name."""
    import content
    have = content.load_items()
    if not have: return
    names = {str(i): r['name'] for i, r in enumerate(_rows(ITEM_FIELDS, exe.raw('items')))}
    for i, r in doc['items'].items():
        if int(i) in have: r['name'] = names[i]


# the key of the species files (docs/mods/species.md) that holds each table field (values as the C writes them)
JSON_KEYS = {'para.name': 'name', 'para.boneCount': 'model.bones', 'para.radius': 'model.radius',
             'para.height': 'model.height', 'para.type': 'attribute', 'para.level': 'level', 'para.special': 'specialties',
             'para.dropItem': 'drop.item', 'para.dropChance': 'drop.percent', 'para.moves': 'techniques',
             'raise.hungerTimes': 'partner.hunger_hours', 'raise.energyCap': 'partner.energy_max',
             'raise.energyThreshold': 'partner.energy_fed', 'raise.energyUsage': 'partner.energy_per_hour',
             'raise.poopTimer': 'partner.poop_timer_10min', 'raise.unk2': 'partner.unk2', 'raise.poopSize': 'partner.poop_size',
             'raise.favoriteFood': 'partner.favorite_food', 'raise.sleepCycle': 'partner.sleep_cycle',
             'raise.favoredRegion': 'partner.favored_region', 'raise.trainingType': 'partner.training_type',
             'raise.defaultWeight': 'partner.birth_weight', 'raise.viewX': 'partner.status_screen_position[0]',
             'raise.viewY': 'partner.status_screen_position[1]', 'raise.viewZ': 'partner.status_screen_position[2]',
             'itemTakeDistance': 'partner.item_distance', 'vlall': 'partner.voice', 'vball': 'voice',
             'originalType': 'effects_like', 'trainingAnims': 'partner.training', 'training2Anims': 'partner.training2',
             'battleMusic': 'battle_music', 'reincarnation': 'reincarnation_stats', 'newGameTechnique': 'new_game_technique'}


SPECIES_BASELINE = os.path.join(ROOT, 'content', 'balance', 'engine', 'species-c.json')


def species_hashes(exe):
    """{symbol: sha1} of the per-species tables of exe as linked (what the C initializes)."""
    import hashlib
    return {sym: hashlib.sha1(exe.raw(t)).hexdigest() for t, _, sym, _ in TABLES if t in SPECIES_TABLES and exe.has(t)}


def write_species_baseline(exe):
    """Record what the C initializes in the per-species tables (tools/species.py sync): a later build whose tables
    hash the same has no C change, so a difference from the species files is an edit of the files."""
    doc = {'_about': 'GENERATED by tools/species.py sync: sha1 of the per-species tables as the C patch series '
                     'initializes them (the build they were synced from). Do not edit.',
           '_from': os.path.relpath(exe.folder, ROOT)}
    doc.update(species_hashes(exe))
    open(SPECIES_BASELINE, 'w').write(json.dumps(doc, indent=1) + '\n')


def species_c_changed(exe):
    """The per-species tables whose C initializers changed since the last species.py sync."""
    base = json.load(open(SPECIES_BASELINE)) if os.path.exists(SPECIES_BASELINE) else {}
    return [sym for sym, h in species_hashes(exe).items() if base.get(sym) != h]


def verify_species(exe, quiet=False):
    """The drift check: every per-species row of exe against the species files, by species and field. A difference
    is an edit of the files when the tables are what the C initialized at the last species.py sync (the baseline,
    content/balance/engine/species-c.json): reported, not an error; when a C patch changed a table since, it fails."""
    have = decode(exe)['species']; want = species_rows(exe); bad = []
    for t in range(NUM_ORIGINAL):
        h, w = have.get(str(t), {}), want[str(t)]
        for k in SP.TABLE_KEYS:
            hv = h.get(k); wv = w.get(k)
            if k == 'newGameTechnique' and hv is not None: hv = tuple(hv)
            if k in ('reincarnation', 'newGameTechnique', 'battleMusic') and hv is None and not exe.has(
                    {'reincarnation': 'reincarnation', 'newGameTechnique': 'newGameTechniques', 'battleMusic': 'battleMusic'}[k]):
                continue
            if k == 'itemTakeDistance' and t == 0: continue
            if hv is None and k in ('raise', 'vlall', 'itemTakeDistance', 'trainingAnims', 'training2Anims'): continue  # no row
            if k in ('para', 'raise') and hv != wv:
                for f in wv:
                    if hv[f] != wv[f]: bad.append((t, JSON_KEYS.get(f'{k}.{f}', f'{k}.{f}'), hv[f], wv[f]))
            elif hv != wv and not (hv is None and wv is None):
                bad.append((t, JSON_KEYS.get(k, k), hv, wv))
    folder = os.path.relpath(exe.folder, ROOT)
    changed = species_c_changed(exe) if exe.compiled else []
    if not quiet or (bad and changed):
        for t, f, c, j in bad:
            print(f'  species {t} {have.get(str(t), {}).get("para", {}).get("name", "")}: {f}: C {c}, JSON {j}')
    if bad and changed:
        print(f'{len(bad)} values of {folder} differ from content/species, and a C patch changed {", ".join(changed)} since '
              f'the last tools/species.py sync: edit the JSON, or, if the C change was meant, '
              f'tools/species.py sync --exe-dir {folder}')
        return 1
    if bad:
        if not quiet:
            print(f'{folder}: {len(bad)} values of content/species differ from the C (edits of the species files: the C '
                  f'is as at the last sync); the build writes the JSON values')
        return 0
    if changed and not quiet:
        print(f'{folder}: the C of {", ".join(changed)} changed since the last sync but equals content/species: '
              f'tools/species.py sync records the new baseline')
    elif not quiet:
        print(f'{folder}: every per-species row equals content/species')
    return 0


def cmd_extract(a):
    exe = Exe(EXTRACTED); doc = annotate(decode(exe))
    write_json(os.path.join(a.o, 'tables.json'), doc)
    maps = {'maps': decode_maps()}; annotate_maps(maps, doc)
    write_json(os.path.join(a.o, 'maps.json'), maps)
    print(f'{os.path.relpath(a.o, ROOT)}/tables.json: {len(doc["species"])} species, {len(doc["techniques"])} techniques, '
          f'{len(doc["items"])} items, tournaments, brain training; maps.json: wild Digimon of {len(maps["maps"])} .MAP files')


def annotate_maps(maps, doc):
    tech = {}
    p = os.path.join(ROOT, 'docs/data/techs.csv')
    if os.path.exists(p):
        for line in open(p).read().splitlines()[1:]:
            i, _, n = line.partition(','); tech[int(i)] = n
    for slots in maps['maps'].values():
        for e in slots.values():
            para = doc['species'].get(str(e['_type']), {}).get('para', {})
            e['_name'] = para.get('name', '')
            ms = para.get('moves', [0xFF] * 16)
            e['_moves'] = [tech.get(ms[m - 0x2E]) if 0x2E <= m < 0x3E else None for m in e['moves']]


def verify_tables(exe, expected):
    enc = encode(expected, exe); bad = []
    import hashlib
    for t, _, sym, _ in TABLES:
        if not exe.has(t): continue
        ok = enc[t] == exe.raw(t)
        f, off, size = exe.where(t)
        print(f'  {sym:24} {f:13} +{off:#08x} {size:5d} B  {hashlib.sha1(exe.raw(t)).hexdigest()[:12]}  '
              + ('identical' if ok else 'DIFFERS'))
        if not ok: bad.append(t)
    return bad


def cmd_verify(a):
    exe = Exe(exe_dir(a)); expected = layered(exe, content=exe.compiled)
    what = 'original + engine layer' if exe.compiled else 'original'
    print(f'{os.path.relpath(exe.folder, ROOT)}: the tables encoded from JSON ({what}) against its bytes:')
    bad = verify_tables(exe, expected); edited = []
    if set(bad) & set(SPECIES_TABLES) and exe.compiled and not verify_species(exe):
        edited = [t for t in bad if t in SPECIES_TABLES]   # edits of the species files (the C is as at the last sync)
        bad = [t for t in bad if t not in SPECIES_TABLES]
    if bad:
        if set(bad) & set(SPECIES_TABLES) and not exe.compiled:
            print('the original executable\'s tables differ from species.py extract of it: a codec bug')
        if set(bad) - set(SPECIES_TABLES):
            d = diff(expected, decode(exe)) or {}
            d['species'] = {t: {k: v for k, v in r.items() if k in EVOLUTION_KEYS} for t, r in d.get('species', {}).items()}
            print(json.dumps(d, indent=1)[:3000])
        sys.exit(f'{len(bad)} tables differ: per-species rows: edit content/species or tools/species.py sync; '
                 f'other tables: the C patches changed them (balance.py sync) or the layer is wrong')
    if edited:
        print(f'{len(TABLES) - len(edited)} tables are byte-identical to what the JSON describes; {len(edited)} per-species '
              f'tables hold the C values where content/species was edited (the build writes the JSON): OK')
    else:
        print(f'all {len(TABLES)} tables are byte-identical to what the JSON describes')


def cmd_sync(a):
    exe = Exe(exe_dir(a))
    if not exe.compiled: sys.exit(f'{exe.folder}: not a compiled build (no SLUS_010.32.elf)')
    d = diff(pad_rows(original_doc(), exe), decode(exe)) or {}
    # the per-species rows are in content/species (tools/species.py sync); this layer keeps the evolution rows
    d['species'] = {t: {k: v for k, v in r.items() if k in EVOLUTION_KEYS} for t, r in d.get('species', {}).items()}
    d['species'] = {t: r for t, r in d['species'].items() if r}
    head = {'_about': 'GENERATED by tools/balance.py sync: the values the C patch series (mods/patches) puts in the '
                      'balance tables, as differences from the original disc. Do not edit: change the C or write an '
                      'override in content/balance/*.json.',
            '_from': os.path.relpath(exe.folder, ROOT)}
    write_json(ENGINE, dict(head, **d))
    n = sum(1 for _ in _walk_leaves(d))
    print(f'{os.path.relpath(ENGINE, ROOT)}: {n} values differ from the original')


def _walk_leaves(d, path=()):
    if isinstance(d, dict):
        for k, v in d.items(): yield from _walk_leaves(v, path + (k,))
    else: yield path, d


def new_species():
    try: return {t: s for t, s in SP.load_content().items()}
    except SystemExit: return {}


def cmd_check(a):
    exe = Exe(exe_dir(a)); base = layered(exe)
    over = load_overrides(a.content)
    errs = validate(over, base, new_species())
    if exe.compiled:
        bad = [t for t, b in encode(base, exe).items() if b != exe.raw(t)]
        if set(bad) & set(SPECIES_TABLES) and verify_species(exe, quiet=True) == 0:
            bad = [t for t in bad if t not in SPECIES_TABLES]     # edits of the species files (the build writes them)
        if bad: errs.append(f'the engine layer is stale for {", ".join(bad)}: tools/balance.py sync')
    exe_over = {k: v for k, v in over.items() if k not in ('maps', 'species')}
    changes = sum(1 for _ in _walk_leaves(diff(base, merge(base, exe_over)) or {}))
    total = sum(1 for _ in _walk_leaves(exe_over))
    for e in errs: print('error:', e)
    files = sorted(glob.glob(os.path.join(a.content, '*.json')))
    print(f'{len(files)} override files: {total} values for the executable tables ({total - changes} equal to the current '
          f'value), {sum(1 for _ in _walk_leaves(over.get("maps", {})))} for wild Digimon: '
          + ('OK' if not errs else f'{len(errs)} errors'))
    sys.exit(1 if errs else 0)


def built_layer(exe):
    """What the build writes into exe's tables: exe's own tables (a compiled executable's are original + engine layer,
    or newer C values a later sync would record: never reverted), the species rows of the species files, then the
    committed JSON (content_layer). rule: the build reads no executable but the one it builds from (not the USA one of
    extracted/, which only the developer tools read: layered)."""
    base = content_layer(with_species_rows(json.loads(json.dumps(decode(exe))), exe))
    if exe.compiled: keep_text_names(base, exe)
    return base


def cmd_build(a):
    src = Exe(exe_dir(a)); base = built_layer(src)
    over = load_overrides(a.content)
    errs = validate(over, base, new_species())
    if errs: sys.exit('\n'.join('error: ' + e for e in errs))
    stale = [t for t, b in encode(base, src).items() if b != src.raw(t) and t in SPECIES_TABLES]
    if stale and verify_species(src, quiet=True):   # a C change the files do not have
        sys.exit('a C patch changed per-species tables that content/species does not say (above)')
    final = merge(base, {k: v for k, v in over.items() if k != 'maps'})
    os.makedirs(a.o, exist_ok=True)
    for f in os.listdir(src.folder):
        p = os.path.join(src.folder, f)
        if os.path.isfile(p) and (f.startswith('SLUS_010.32') or f.endswith('_REL.BIN')):
            shutil.copy2(p, os.path.join(a.o, f))
    out = Exe(a.o); changed = 0
    for t, blob in encode(final, out).items():
        old = out.raw(t)
        if blob != old:
            changed += sum(x != y for x, y in zip(blob, old)); out.write(t, blob)
    for f, data in out.files.items():
        open(os.path.join(a.o, f), 'wb').write(data)
    print(f'{os.path.relpath(a.o, ROOT)}: executable and overlays with all {len(TABLES)} tables encoded from JSON, '
          f'{changed} bytes differ from {os.path.relpath(src.folder, ROOT)}')
    if not a.no_maps:
        for rel, dst in build_maps(os.path.join(a.o, 'maps'), dict(x.split('=', 1) for x in a.file or [])):
            print(f'FILE: {rel}={os.path.abspath(dst)}')


def build_maps(out, sources=(), overrides=None):
    """The wild Digimon of content/maps (tools/content.py) written into the .MAP files the story did not edit (`sources`,
    the disc paths the story compiler replaced: the story starts from content/maps itself) -> [(disc path, file under
    out)], including maps whose generated bytes equal this base's input. They read extracted/ and content/ only, no executable: tools/derive's
    balance step makes them before the executable (`build --no-maps` then leaves them out)."""
    import content
    done = []
    for name, rel in content.map_files().items():
        if rel in sources: continue
        src = (overrides or {}).get(rel, os.path.join(EXTRACTED, rel))
        data = open(src, 'rb').read(); new = content.build_map(name, data)
        # The package records outputs on USA, then replays them on other bases.
        # Omitting a USA-identical result would copy another base's intermediate
        # enemy list instead of the content/maps result (notably Japanese maps).
        dst = os.path.join(out, rel); os.makedirs(os.path.dirname(dst), exist_ok=True)
        open(dst, 'wb').write(new); done.append((rel, dst))
    return done


def effective(a):
    exe = Exe(exe_dir(a)); doc = merge(layered(exe), load_overrides(a.content))
    maps_over = doc.pop('maps', {})
    for b in doc['species'].values():                    # shorter path lists: -1 = empty slot (as encode writes them)
        if 'evoPaths' in b:
            b['evoPaths'] = {k: (list(b['evoPaths'][k]) + [-1] * n)[:n] for k, n in (('from', 5), ('to', 6))}
    for t, s in sorted(new_species().items()):
        if t < NUM_ORIGINAL: continue
        try: r = SP.species_record(s)
        except SystemExit as ex: print(f'warning: {s["_path"]}: {ex}'); continue
        b = {'para': r['para']}
        if r['flags'] & SP.FLAG_PARTNER:
            b.update(raise_=r['raise'], evoReqs=r['evoReqs'], evoGains=r['evoGains'], evoPaths=r['evoPaths'],
                     itemTakeDistance=r['itemTakeDistance'])
            b['raise'] = b.pop('raise_')
        doc['species'][str(t)] = b
    return doc, maps_over


def cmd_dump(a):
    doc, _ = effective(a)
    write_json(a.o, annotate(doc))
    print(f'{os.path.relpath(a.o, ROOT)}: {len(doc["species"])} species (every layer merged)')


def cmd_show(a):
    doc, _ = effective(a); annotate(doc)
    s = doc['species'].get(str(a.id))
    if s is None: sys.exit(f'no species {a.id}')
    print(json.dumps(ordered(s), indent=1))


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument('--content', default=CONTENT, help='override folder (default content/balance)')
    sub = ap.add_subparsers(dest='cmd', required=True)
    p = sub.add_parser('extract'); p.add_argument('-o', default=os.path.join(ROOT, 'build/balance/original')); p.set_defaults(f=cmd_extract)
    for name, f in (('verify', cmd_verify), ('sync', cmd_sync), ('check', cmd_check)):
        p = sub.add_parser(name); p.add_argument('--exe-dir'); p.set_defaults(f=f)
    p = sub.add_parser('build'); p.add_argument('--exe-dir'); p.add_argument('-o', required=True)
    p.add_argument('--file', action='append', help='DEST=SRC: a .MAP already replaced (DWS output) to patch instead of the original')
    p.add_argument('--no-maps', action='store_true', help='only the executable and overlays (the maps: tools/derive\'s balance step, build_maps)')
    p.set_defaults(f=cmd_build)
    p = sub.add_parser('dump'); p.add_argument('--exe-dir'); p.add_argument('-o', default=os.path.join(ROOT, 'build/balance/effective.json')); p.set_defaults(f=cmd_dump)
    p = sub.add_parser('show'); p.add_argument('id', type=int); p.add_argument('--exe-dir'); p.set_defaults(f=cmd_show)
    a = ap.parse_args()
    os.environ['BALANCE_CONTENT'] = os.path.abspath(a.content)     # species.py (ids >= 180) reads the same folder
    a.f(a)


if __name__ == '__main__':
    main()
